INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'Same underlying event, separate filings: the NIS2 24h/72h/1-month cascade goes to the BSI/BBK Meldestelle, the GDPR Art. 33 notification, in phases if need be (Art. 33(4)), to the data protection authority.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = '3.3' AND rb."code" = 'G-BRC.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
