INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'The risk treatment plan lists measures Art. 32 asks for too; Art. 32 asks for the measures, not an approval.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = '2.4' AND rb."code" = 'G-TOM.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
