INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'The process shape carries over: CIR 2.1.2 requires identification, analysis, assessment and treatment of risks, which is the loop Art. 9(2) describes. The scope does not: CIR 2.1 is bounded to risks to network and information systems, while Art. 9 covers risks to health, safety and fundamental rights and pulls in post-market monitoring data (Art. 9(2)(c)). Both sides require residual risk to be accepted, but against different criteria (Art. 9(5) vs CIR 2.1.1). Art. 9(10) lets you combine the procedures; it does not merge the duties.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = 'AI-RSK.1' AND rb."code" = '2.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'Annual AI risk review feeds the same asset-classification update NIS2 expects.', 'equivalent'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = 'AI-RSK.2' AND rb."code" = '2.3' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'AI incident response procedure overlaps with the NIS2 incident handling policy under CIR 3.1.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = 'AI-INC.1' AND rb."code" = '3.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'Same underlying event, separate filings: the AI Act Art. 73 report goes to the market surveillance authority, the NIS2 24h/72h cascade to the BSI Meldestelle. Art. 73(2) sets 15 days, but a serious and irreversible disruption of the management or operation of critical infrastructure (Art. 3(49)(b)) is due within two days under Art. 73(3), and a death within 10 days under Art. 73(4). Entities in NIS2 scope should plan for the two-day clock.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = 'AI-INC.2' AND rb."code" = '3.3' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
